for p in [(9,8),(10,7),(10,9),(11,8)]: marker_owners[p]=None
allmarks=set(marker_owners)
hpaint={}; vpaint={}
for r,c,col in centers:
 for dr,dc,paint in [(0,-1,hpaint),(0,1,hpaint),(-1,0,vpaint),(1,0,vpaint)]:
