  while 0<=i<n and 0<=j<n:
   if (i,j) in allmarks:
    if marker_owners[(i,j)]==(r,c):
     i+=dr;j+=dc;continue
    break
   # colored center blocks rays from other objects
   if any((i,j)==(rr,cc) for rr,cc,_ in centers): break
   paint[(i,j)]=col
   i+=dr;j+=dc
# output centers and marks, then horizontal, vertical (vertical wins); markers preserved
out=[[0]*n for _ in range(n)]
for (r,c),v in hpaint.items():out[r][c]=v
for (r,c),v in vpaint.items():out[r][c]=v
for r,c,col in centers:out[r][c]=col
